/**
 * Vendandor logos: inlined data URIs fetched from models.dev /logos/{id}.svg.
 * Keyed by the MODEL_CATALOG entry provider display name so the pricing table
 * / model rows can render a real vendor mark before the model name. Vendors not
 * listed here fall back to a brand-color letter badge in the UI.
 */
export const VENDOR_LOGOS: Readonly<Record<string, string>> = {
  "Anthropic": 'data:image/svg+xml;base64,',
  "Cohere": 'data:image/svg+xml;base64,',
  "DeepSeek": 'data:image/svg+xml;base64,',
  "Google": 'data:image/svg+xml;base64,',
  "Meta": 'data:image/svg+xml;base64,',
  "MiniMax": 'data:image/svg+xml;base64,',
  "Mistral AI": 'data:image/svg+xml;base64,',
  "OpenAI": 'data:image/svg+xml;base64,',
  "xAI": 'data:image/svg+xml;base64,',
  "阿里通义": 'data:image/svg+xml;base64,',
  "阶跃星辰": 'data:image/svg+xml;base64,',
  "美团": 'data:image/svg+xml;base64,',
  "腾讯混元": 'data:image/svg+xml;base64,',
  "小米": 'data:image/svg+xml;base64,',
  "月之暗面": 'data:image/svg+xml;base64,',
  "智谱 AI": 'data:image/svg+xml;base64,',
  // 字节豆包 → 火山引擎；百度文心 → 百度。models.dev 无这两个 provider，
  // 火山引擎取自 lobehub mono 图标，百度取自 Simple Icons（CC0）。
  "百度文心": 'data:image/svg+xml;base64,',
  // 火山引擎（字节豆包）mono 图标，取自 lobehub（fill=currentColor，继承品牌色）。
  "字节豆包": 'data:image/svg+xml;base64,',
};

export function vendorLogoOf(provider: string): string | undefined {
  return VENDOR_LOGOS[provider]
}
